using System;using System.Collections.Generic;using System.Linq;using RimWorld;using RimWorld.Planet;using UnityEngine;using Verse;using Verse.AI;
namespace ElementalHearts {
 public static class AuroraIncarnate {
  public const string DefName="EH_AuroraIncarnate",Ritual="EH_TranscendAurora",CombatJob="EH_AuroraTechnique";
  public const int Kills=300,Days=900000,RitualTicks=480,SkillCount=7;public const float ShockFactor=.25f;
  public static readonly string[] Names={"Rimefall Crescent","Aurora Blitz","Frostcrown Waltz","Aurora Dominion","Aurora Cataclysm","Mirrorfrost Reversal","Throne of Endless Winter"};
  public static readonly string[] Icons={"RimefallCrescent","AuroraBlitz","FrostcrownWaltz","AuroraDominion","AuroraCataclysm","MirrorfrostReversal","ThroneOfEndlessWinter","TranscendAurora","RimePressure"};
  public static readonly int[] Cooldowns={180,300,420,1080,1440,540,2400};public static readonly float[] Ranges={22,18,7,24,6,5,28};
  public static bool Active(Pawn p){return p!=null&&p.health!=null&&p.health.hediffSet.hediffs.Any(h=>h.def.defName==DefName);}
  public static bool Busy(Pawn p){return p!=null&&p.CurJobDef!=null&&(p.CurJobDef.defName==CombatJob||p.CurJobDef.defName==Ritual||p.CurJobDef.defName==AuroraUtility.Depart||p.CurJobDef.defName==AuroraUtility.Arrive);}
  public static bool Impacting(Pawn p){var d=p==null||p.jobs==null?null:p.jobs.curDriver as JobDriver_AuroraTechnique;return d!=null&&d.impacting;}
  public static Texture2D Icon(int i){return ContentFinder<Texture2D>.Get("UI/Commands/ElementalHearts/AuroraIncarnate/"+Icons[i]);}
  public static HediffComp_AuroraMastery Mastery(Pawn p){return p==null||p.health==null?null:p.health.hediffSet.hediffs.Select(h=>h.TryGetComp<HediffComp_AuroraMastery>()).FirstOrDefault(c=>c!=null);}
  public static string Problem(Pawn p){var m=Mastery(p);if(!GlacialEvolution.Active(p)||m==null)return "Requires Glacial ascension.";m.EnsureStarted();if(m.kills<Kills||m.Age<Days)return "Requires 300 new hostile non-animal kills and 15 days as Glacial.";return CodexOrders.OrderProblem(p);}
  public static bool Begin(Pawn p){return Problem(p)==null&&p.jobs.TryTakeOrderedJob(JobMaker.MakeJob(DefDatabase<JobDef>.GetNamed(Ritual),p),JobTag.Misc);}
  public static bool Complete(Pawn p){
   var m=Mastery(p);if(!GlacialEvolution.Active(p)||m==null||m.kills<Kills||m.Age<Days||!ElementalTeaching.Ready(p))return false;
   var water=HediffComp_WaterAbilities.On(p);if(water==null)return false;var remaining=Enumerable.Range(0,4).Select(i=>water.Remaining((WaterPower)i)).ToArray();var explosion=HediffComp_GlacialExplosion.On(p);int burst=explosion==null?0:Math.Max(0,explosion.readyAt-Find.TickManager.TicksGame);
   // Rebind the same root. In particular retain WaterDefense, recovery, transform,
   // personal gear, Pressure ownership and the original automation save keys.
   var root=m.parent;AzureLineage.Rebind(root,DefDatabase<HediffDef>.GetNamed(DefName));p.health.Notify_HediffChanged(root);var next=HediffComp_AuroraIncarnate.On(p);int now=Find.TickManager.TicksGame;for(int i=0;i<4;i++)next.readyAt[i]=now+remaining[i];next.readyAt[4]=now+burst;next.readyAt[6]=now+remaining[3];
   var transform=root.TryGetComp<HediffComp_ElementalTransform>();if(transform!=null)transform.RebuildAzureKit();foreach(var c in root.comps)c.Notify_Spawned();p.Drawer.renderer.SetAllGraphicsDirty();AuroraVfx.Burst(p,16,p.DrawPos,18,48);ElementalAudio.Ability(p,ElementalSound.Burst);Messages.Message(p.LabelShort+" has transcended as Aurora Incarnate!",p,MessageTypeDefOf.PositiveEvent,false);return true;
  }
 }
 public sealed class HediffCompProperties_AuroraMastery:HediffCompProperties{public HediffCompProperties_AuroraMastery(){compClass=typeof(HediffComp_AuroraMastery);}}
 public sealed class GameComponent_AuroraMasteryInit:GameComponent {
  public GameComponent_AuroraMasteryInit(Game game){}
  public override void FinalizeInit(){var props=DefDatabase<HediffDef>.GetNamed(GlacialEvolution.DefName).comps.First(c=>c.compClass==typeof(HediffComp_AuroraMastery));foreach(var p in PawnsFinder.AllMapsWorldAndTemporary_AliveOrDead){if(!GlacialEvolution.Active(p))continue;var m=AuroraIncarnate.Mastery(p);if(m==null){var root=p.health.hediffSet.hediffs.First(h=>h.def.defName==GlacialEvolution.DefName) as HediffWithComps;m=new HediffComp_AuroraMastery{parent=root,props=props};root.comps.Add(m);}m.EnsureStarted();}}
 }
 public sealed class HediffComp_AuroraMastery:HediffComp {
  public int kills,startedAt=-1;HashSet<int> victims=new HashSet<int>();public int Age{get{return startedAt==-1?0:Math.Max(0,Find.TickManager.TicksGame-startedAt);}}
  public void EnsureStarted(){if(startedAt==-1&&GlacialEvolution.Active(Pawn))startedAt=Find.TickManager.TicksGame;}
  public override void Notify_Spawned(){LongEventHandler.ExecuteWhenFinished(EnsureStarted);}
  public override void CompPostTickInterval(ref float adjustment,int delta){EnsureStarted();}
  public override void CompExposeData(){Scribe_Values.Look(ref kills,"EH_auroraMasteryKills");Scribe_Values.Look(ref startedAt,"EH_auroraMasteryStarted",-1);Scribe_Collections.Look(ref victims,"EH_auroraMasteryVictims",LookMode.Value);if(victims==null)victims=new HashSet<int>();}
  public override void Notify_KilledPawn(Pawn victim,DamageInfo? info){EnsureStarted();if(kills<300&&GlacialEvolution.Active(Pawn)&&victim!=null&&AzureRules.CountKill(victim.HostileTo(Pawn),victim.RaceProps.Animal,victim==Pawn)&&victims.Add(victim.thingIDNumber))kills++;}
  public void MakeReady(){EnsureStarted();kills=Math.Max(kills,AuroraIncarnate.Kills);startedAt=Find.TickManager.TicksGame-AuroraIncarnate.Days;if(startedAt==-1)startedAt=-2;}
  public override string CompTipStringExtra{get{return AuroraIncarnate.Active(Pawn)?"Aurora transcendence complete.":"Aurora mastery: "+kills+" / 300 new kills; "+(Age/60000f).ToString("0.0")+" / 15 Glacial days.";}}
  public override IEnumerable<Gizmo> CompGetGizmos(){if(!ElementalCombatPolicy.Controlled(Pawn)||!GlacialEvolution.Active(Pawn))yield break;EnsureStarted();var command=new Command_Action{defaultLabel="Transcend: Aurora Incarnate",defaultDesc=CompTipStringExtra+"\nPerform an eight-second frost coronation. Seven sovereign forms, Winterglass, winter-prince regalia, northern lights and 650% Moving capacity. Free; interruption preserves readiness.",icon=AuroraIncarnate.Icon(7),groupable=false,action=()=>AuroraIncarnate.Begin(Pawn)};var why=AuroraIncarnate.Problem(Pawn);if(why!=null)command.Disable(why);yield return command;if(DebugSettings.godMode)yield return new DevEvolutionReadyCommand{isEligible=()=>GlacialEvolution.Active(Pawn),defaultLabel="DEV: Transcend-Ready",defaultDesc="God Mode only. Unlock Aurora requirements, then press Transcend.",icon=AuroraIncarnate.Icon(7),groupable=false,action=()=>{if(DebugSettings.godMode)MakeReady();}};}
 }
 public sealed class JobDriver_TranscendAurora:JobDriver {
  int started=-1,cue=-1;bool committed;public float Progress{get{return started<0?0:Mathf.Clamp01((Find.TickManager.TicksGame-started)/(float)AuroraIncarnate.RitualTicks);}}
  public override bool TryMakePreToilReservations(bool errorOnFailed){return true;}
  public override void ExposeData(){base.ExposeData();Scribe_Values.Look(ref started,"EH_auroraRitualStart",-1);Scribe_Values.Look(ref cue,"EH_auroraRitualCue",-1);Scribe_Values.Look(ref committed,"EH_auroraRitualCommitted");}
  void Hold(){int now=Find.TickManager.TicksGame;if(started<0)started=now;pawn.pather.StopDead();pawn.Rotation=Rot4.South;AuroraVfx.Track(pawn);int elapsed=now-started;int next=elapsed<120?0:elapsed<300?1:elapsed<420?2:3;if(next>cue){cue=next;AuroraVfx.Burst(pawn,20,pawn.DrawPos,6+next*2,90);if(next>=1)AuroraVfx.Burst(pawn,5,pawn.DrawPos,7+next*2,90);ElementalAudio.Ability(pawn,next<3?ElementalSound.Charge:ElementalSound.Impact);}}
  protected override IEnumerable<Toil> MakeNewToils(){this.FailOn(()=>!ElementalTeaching.Ready(pawn)||!GlacialEvolution.Active(pawn)||ElementalAnimationBridge.ExternallyControlled(pawn));var wait=Toils_General.Wait(AuroraIncarnate.RitualTicks);wait.handlingFacing=true;wait.initAction=Hold;wait.tickAction=Hold;wait.WithProgressBarToilDelay(TargetIndex.A);yield return wait;yield return Toils_General.Do(()=>{if(committed)return;committed=true;AuroraIncarnate.Complete(pawn);});}
 }
 public sealed class HediffCompProperties_AuroraIncarnate:HediffCompProperties{public HediffCompProperties_AuroraIncarnate(){compClass=typeof(HediffComp_AuroraIncarnate);}}
 public sealed class HediffComp_AuroraIncarnate:HediffComp {
  internal int lastMeleeVisualTick=-9999;public bool autoStep=true,travelMode;public int stepReadyAt,nextStepCheck,nextThink,combo,wardUntil;public PlanetTile travelDestination=PlanetTile.Invalid;public List<int> readyAt=new List<int>{0,0,0,0,0,0,0};
  public static HediffComp_AuroraIncarnate On(Pawn p){return p==null||p.health==null?null:p.health.hediffSet.hediffs.Select(h=>h.TryGetComp<HediffComp_AuroraIncarnate>()).FirstOrDefault(c=>c!=null);}
  public void EnsureCooldowns(){if(readyAt==null)readyAt=new List<int>();while(readyAt.Count<7)readyAt.Add(0);if(readyAt.Count>7)readyAt.RemoveRange(7,readyAt.Count-7);}
  public override void CompExposeData(){Scribe_Collections.Look(ref readyAt,"EH_auroraCooldowns",LookMode.Value);Scribe_Values.Look(ref autoStep,"EH_auroraStepAuto",true);Scribe_Values.Look(ref travelMode,"EH_auroraTravelMode");Scribe_Values.Look(ref stepReadyAt,"EH_auroraStepReadyAt");Scribe_Values.Look(ref nextStepCheck,"EH_auroraStepCheck");Scribe_Values.Look(ref travelDestination,"EH_auroraTravelDestination",PlanetTile.Invalid);Scribe_Values.Look(ref nextThink,"EH_auroraNextThink");Scribe_Values.Look(ref combo,"EH_auroraCombo");Scribe_Values.Look(ref wardUntil,"EH_auroraWardUntil");EnsureCooldowns();if(travelMode)autoStep=false;combo=Math.Max(0,combo)%5;}
  public override void Notify_Spawned(){AuroraVfx.Track(Pawn);}
  public override void CompPostPostAdd(DamageInfo? info){AuroraVfx.Track(Pawn);}
  public override void CompPostTickInterval(ref float adjustment,int delta){if(!Pawn.Spawned||Pawn.Dead)return;RimeStep.Tick(this);Auto();}
  public int Remaining(int n){EnsureCooldowns();return Math.Max(0,readyAt[n]-Find.TickManager.TicksGame);}
  public bool CanAct{get{var defense=HediffComp_WaterDefense.On(Pawn);return AuroraIncarnate.Active(Pawn)&&defense!=null&&defense.Able&&!defense.PendingCounter&&HediffComp_ElementalTransform.Active(Pawn)&&!HediffComp_ElementalTransform.Transforming(Pawn)&&!ElementalAnimationBridge.Controlled(Pawn)&&!ElementalBestow.Busy(Pawn)&&(Pawn.CurJobDef==null||Pawn.CurJobDef.defName!="EH_WaterCounter");}}
  public bool Start(int n,LocalTargetInfo target,bool automatic=false){if(n<0||n>=7||!CanAct||Remaining(n)>0)return false;var job=AuroraCombat.Plan(Pawn,n,target,automatic);if(job==null)return false;Pawn.jobs.StartJob(job,JobCondition.InterruptForced,resumeCurJobAfterwards:IncarnateCombatFlow.SuspendOnce(Pawn,automatic),cancelBusyStances:true);if(Pawn.CurJob!=job)return false;readyAt[n]=Find.TickManager.TicksGame+AuroraIncarnate.Cooldowns[n];nextThink=Find.TickManager.TicksGame+12;return true;}
  public void Auto(){int now=Find.TickManager.TicksGame;if(now<nextThink)return;nextThink=now+12;var defense=HediffComp_WaterDefense.On(Pawn);if(defense==null||!defense.Active||!CanAct||Pawn.CurJob==null||ElementalCombatPolicy.Controlled(Pawn)&&IncarnateCombatFlow.BlockingOrders(Pawn))return;if(ElementalCombatPolicy.Controlled(Pawn)&&Pawn.CurJobDef!=JobDefOf.AttackMelee&&Pawn.CurJobDef!=JobDefOf.Wait_Combat&&!SearchAndDestroyBridge.IsApproach(Pawn,Pawn.CurJob))return;if(Pawn.stances.FullBodyBusy&&!(Pawn.stances.curStance is Stance_Cooldown))return;if(Remaining(4)==0&&AuroraCombat.Crowd(Pawn)>=2&&Start(4,Pawn,true))return;var targets=AuroraCombat.Targets(Pawn,Pawn.Position,28,16);if(targets.Count==0)return;var target=IncarnateCombatFlow.Target(Pawn,targets[0]);int[] order={1,2,0,3,6};for(int i=0;i<5;i++){int n=order[(combo+i)%5];if(Start(n,n==2?new LocalTargetInfo(Pawn):new LocalTargetInfo(target),true)){combo=(combo+i+1)%5;return;}}}
  public override IEnumerable<Gizmo> CompGetGizmos(){if(ElementalCombatPolicy.Controlled(Pawn)&&Pawn.Spawned&&!Pawn.Dead)yield return RimeStep.Command(Pawn);}
  public IEnumerable<Gizmo> Commands(){for(int i=0;i<7;i++){int power=i;Command command;if(i==2||i==4)command=new Command_Action{action=()=>Start(power,Pawn)};else command=new Command_Target{targetingParams=new TargetingParameters{canTargetPawns=true,canTargetLocations=i==0||i==3||i==6,canTargetBuildings=false,canTargetItems=false,canTargetSelf=false,validator=t=>Pawn.Spawned&&t.Cell.InBounds(Pawn.Map)&&!t.Cell.Fogged(Pawn.Map)&&Pawn.Position.DistanceToSquared(t.Cell)<=AuroraIncarnate.Ranges[power]*AuroraIncarnate.Ranges[power]},action=t=>{if(!Start(power,t))Messages.Message("No valid enemy, safe route or ready technique.",MessageTypeDefOf.RejectInput,false);},onUpdate=t=>{if(Pawn.Spawned)GenDraw.DrawRadiusRing(Pawn.Position,AuroraIncarnate.Ranges[power]);}};command.defaultLabel=AuroraIncarnate.Names[i];command.defaultDesc=AuroraCombat.Descriptions[i]+"\nFree. "+AuroraIncarnate.Cooldowns[i]/60+"s recharge, spent on interruption. Shared Auto/Off/Non-lethal controls. One committed hit per victim; aurora and snow frames deal no extra damage.";command.icon=AuroraIncarnate.Icon(i);command.groupable=false;if(!CanAct)command.Disable("Transform, draft and finish the current action first.");else if(Remaining(i)>0)command.Disable("Recharging: "+Math.Ceiling(Remaining(i)/60f)+"s");yield return command;}}
  public override string CompTipStringExtra{get{return "Sovereign winter: Pressure is capped at three stacks per caster/victim. Dominion and Throne consume only your marks for up to 20% stronger shatter and a brief ward. Cold/hypothermia immunity; electrical shock chance/duration reduced by 75%.";}}
 }
